SELECT nr.id, nr.customer_id, nr.project_id, nr.caregiver_id, nr.execution_date, nr.execution_time, nr.duration, nr.execution_status, nr.notes, nr.created_at, c.name as customer_name, np.project_name, np.project_category, np.standard_duration, u.real_name as caregiver_name FROM nursing_records nr JOIN customers c ON nr.customer_id = c.id JOIN nursing_projects np ON nr.project_id = np.id JOIN users u ON nr.caregiver_id = u.id
AND ( c.name LIKE CONCAT('%', #{searchKeyword}, '%') OR np.project_name LIKE CONCAT('%', #{searchKeyword}, '%') OR u.real_name LIKE CONCAT('%', #{searchKeyword}, '%') OR nr.notes LIKE CONCAT('%', #{searchKeyword}, '%') )
AND nr.execution_status = #{executionStatus}
AND nr.execution_date >= #{startDate}
AND nr.execution_date <= #{endDate}
AND nr.customer_id = #{customerId}
AND nr.project_id = #{projectId}
AND nr.caregiver_id = #{caregiverId}
ORDER BY nr.execution_date DESC, nr.execution_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM nursing_records nr
JOIN customers c ON nr.customer_id = c.id
JOIN nursing_projects np ON nr.project_id = np.id
JOIN users u ON nr.caregiver_id = u.id


        AND (
        c.name LIKE CONCAT('%', #{searchKeyword}, '%')
        OR np.project_name LIKE CONCAT('%', #{searchKeyword}, '%')
        OR u.real_name LIKE CONCAT('%', #{searchKeyword}, '%')
        OR nr.notes LIKE CONCAT('%', #{searchKeyword}, '%')
        )


        AND nr.execution_status = #{executionStatus}


        AND nr.execution_date >= #{startDate}


        AND nr.execution_date <= #{endDate}


        AND nr.customer_id = #{customerId}


        AND nr.project_id = #{projectId}


        AND nr.caregiver_id = #{caregiverId}

SELECT nr.*, c.name as customer_name, np.project_name, np.project_category, u.real_name as caregiver_name FROM nursing_records nr JOIN customers c ON nr.customer_id = c.id JOIN nursing_projects np ON nr.project_id = np.id JOIN users u ON nr.caregiver_id = u.id WHERE nr.caregiver_id = #{caregiverId}
AND nr.execution_date >= #{startDate}
AND nr.execution_date <= #{endDate}
ORDER BY nr.execution_date DESC, nr.execution_time DESC

SELECT nr.*, c.name as customer_name, np.project_name, np.project_category, u.real_name as caregiver_name FROM nursing_records nr JOIN customers c ON nr.customer_id = c.id JOIN nursing_projects np ON nr.project_id = np.id JOIN users u ON nr.caregiver_id = u.id WHERE nr.project_id = #{projectId}
AND nr.execution_date >= #{startDate}
AND nr.execution_date <= #{endDate}
ORDER BY nr.execution_date DESC, nr.execution_time DESC

SELECT nr.*, c.name as customer_name, np.project_name, np.project_category, u.real_name as caregiver_name FROM nursing_records nr JOIN customers c ON nr.customer_id = c.id JOIN nursing_projects np ON nr.project_id = np.id JOIN users u ON nr.caregiver_id = u.id WHERE nr.execution_date = CURDATE()
AND nr.caregiver_id = #{caregiverId}
ORDER BY nr.execution_time DESC

SELECT * FROM nursing_records
WHERE customer_id = #{customerId}
  AND project_id = #{projectId}
  AND execution_date = #{executionDate}

